The fix proposed in the incident review (ioredis):
const gotLock = (await redis.set(`lock:${key}`, token, "EX", 5, "NX")) === "OK";
if (gotLock) {
  try {
    const data = await db.loadCourseDetail(slug);      // about 180 ms, 2 s at worst
    await redis.set(key, JSON.stringify(data), "EX", 3600);
    return data;
  } finally {
    await redis.eval(RELEASE_IF_OWNER, 1, `lock:${key}`, token); // DEL only if the value is still our token
  }
}
return waitForCachedValue(key);                          // poll the key every 50 ms, up to 1 s

Statement: "Only the request that wins SET NX loads from PostgreSQL while the lock exists, and if that request's process dies before it releases the lock, the lock disappears by itself after at most 5 seconds so another request can load."
